window.RP_SESSION={"id":"S-36b8ac9873ba","messages":[{"id":"RP-III-0044587","time":"2026-03-09T22:12:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"한적한 공터에서 한쪽 무릎을 꿇고 하늘을 올려다본다. 그러다 눈으 감고 기도하는 것 같다. \n\n위대한 빛, 라운데라시여. 이 방황하는 어린양이 한 모험가 길드에 몸을 의탁하였나이다. \n\n제가 가고자 하는 길이 가시밭길일 수 있습니다. 하지만 진실을 알게된 이상, 가만히 있을 수 없었습니다. 부디 제가 가는 길에 어둠이 드리울지라도 믿은이 변하지 않고 나아갈 수 있는 용기 주옵소서\n서툴고 넘어져도 라운데라님 앞에서 넘어지겠나이다.","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044588","time":"2026-03-09T22:13:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"그래, 신의 말씀을 해석하는 것은 인간이고 인간은 완벽하지 않다. 그러니 제국도 교단도 나도 잘못을 저지를 수 있다.","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044589","time":"2026-03-09T22:14:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"그저 라운데라님 곁에 설때 부끄럽지 않도록, 매 삶에 최선을 다해 살 뿐이다. 그거면, 된 것이다.","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044590","time":"2026-03-09T22:14:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"자리에서 무릎을 펴고 일어나 무릎을 툭툭 털어낸다.","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044591","time":"2026-03-09T22:18:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044592","time":"2026-03-09T22:18:00+09:00","room":"RP III","name":"에렌 아르슬란","profile":"리안 실베스트리스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-20bc838e3a9a"]},{"id":"RP-III-0044593","time":"2026-03-09T22:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]},{"id":"RP-III-0044594","time":"2026-03-09T22:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
